  Object.assign(EN, {"Füge Freunde per Benutzername hinzu und chatte mit ihnen. Das läuft über dein Cloudy-Konto, ein extra Freundesserver ist nicht nötig.": "Add friends by username and chat with them. It runs through your Cloudy account – no extra friends server needed.", "Skin im Start-Banner zeigen": "Show skin in the home banner", "Freunde & Chat laufen jetzt direkt über dein Cloudy-Konto: Freund per Benutzername hinzufügen („+“) und chatten, ohne extra Freundesserver (braucht die neue app.js)": "Friends & chat now run directly through your Cloudy account: add a friend by username (“+”) and chat, no extra friends server (needs the new app.js)", "Start-Banner: Dein Skin mit Cosmetics steht rechts hinter den Knöpfen und schaut dem Mauszeiger nach (in den Einstellungen abschaltbar)": "Home banner: your skin with cosmetics stands on the right behind the buttons and looks at your mouse pointer (can be turned off in Settings)", "Shop: Filter „Alle · Nicht gekauft · Gekauft“; die 3D-Vorschau sitzt weiter mittig": "Shop: filter “All · Not owned · Owned”; the 3D preview sits more centered", "Codes sehen jetzt so aus: MQZU-VU2J-AP2Y (Eingabe mit oder ohne Bindestriche, Groß-/Kleinschreibung egal)": "Codes now look like this: MQZU-VU2J-AP2Y (enter with or without dashes, case does not matter)", "Admin: „Zugangscode entziehen“ pro Nutzer; Meldung nach Item entfernen/hinzufügen": "Admin: “Revoke access code” per user; message after removing/adding items", "Update-Knopf hat 10 Sekunden Wartezeit gegen Spammen; Updates kommen immer von Bensinice/Cloudy-Client": "The update button has a 10 second wait against spamming; updates always come from Bensinice/Cloudy-Client", "Mini-Player: Steuerknöpfe (Pause, Weiter, Zurück, Lautstärke) lösen jetzt zuverlässig aus – der Windows-Befehl wurde vorher von der Kommandozeile zerlegt": "Mini player: the controls (pause, next, previous, volume) now trigger reliably – the Windows command used to be mangled by the command line", "Die Wolke oben dreht sich jetzt auch, wenn Windows Animationen abgeschaltet hat": "The cloud at the top now spins even when Windows has animations turned off", "Entfernte Items kommen nicht mehr sofort von einem veralteten Launcher zurück": "Removed items no longer come straight back from an outdated launcher"});
  Object.assign(EN, {"Update erzwingen":"Force update","Das neueste Release von GitHub jetzt erzwingen? Es wird installiert, auch wenn es nicht neuer oder sogar älter ist.":"Force the latest GitHub release now? It will be installed even if it is not newer or even older.","Suche Release …":"Looking for release …","Keine GitHub-Quelle gesetzt.":"No GitHub source set.","Lädt das neueste GitHub-Release und installiert es – egal ob neuer, gleich oder älter":"Downloads the latest GitHub release and installs it – whether newer, equal or older"});
  Object.assign(EN, {"Einstellungen: „Update erzwingen“ lädt das neueste GitHub-Release und installiert es immer – auch wenn es nicht neuer oder sogar älter ist":"Settings: “Force update” downloads the latest GitHub release and always installs it – even if it is not newer or even older"});
  Object.assign(EN, {"Cloudy Coins": "Cloudy Coins", "Neues Item!": "New item!", "Klicken für weiter": "Click to continue", "Klicken zum Schließen": "Click to close", "Code einlösen zeigt jetzt eine Belohnungs-Animation: Lichtstrahlen, die Karte des Items dreht sich auf (3D) und die Coins zählen hoch": "Redeeming a code now shows a reward animation: light rays, the item card flips open (3D) and the coins count up"});
  Object.assign(EN, {"Einlösen": "Redeem", "Eingelöst": "Redeemed", "Chat: Vor jeder Nachricht steht der Skin-Kopf des Absenders (dein gewählter Skin wird mit deinem Konto geteilt)": "Chat: the sender's skin head appears before every message (your chosen skin is shared via your account)", "Chat: Steht in einer Nachricht ein Code (z. B. MQZU-VU2J-AP2Y), erscheint darunter ein Knopf „Einlösen“": "Chat: if a message contains a code (e.g. MQZU-VU2J-AP2Y), a “Redeem” button appears under it", "Lyrics-Test: prüft jetzt jede Quelle einzeln mit dem laufenden Song (sonst mit einem Beispiel) und zeigt Zeilen und Zeit; ohne Spiel erkannte er vorher keinen Song": "Lyrics test: now checks every source separately with the song that is playing (or a sample) and shows lines and time; before, it detected no song outside the game"});
  Object.assign(EN, {"Minecraft-Start: Ein veraltetes selbst gebautes Cloudy-Client-Jar verdrängt nicht mehr das neue mitgelieferte – dadurch startete der Launcher nach jedem Update minutenlang einen Neubau („Cloudy Client wird aktualisiert …“)": "Minecraft start: an outdated self-built Cloudy Client jar no longer overrides the new bundled one – which made the launcher rebuild for minutes after every update (“Updating Cloudy Client …”)"});
