      if (lang !== 'de') { const cur = n.nodeValue, o = orig.has(n) && tr(orig.get(n)) === cur ? orig.get(n) : cur, t = tr(o); if (t !== cur) { orig.set(n, o); n.nodeValue = t; } else if (t !== o) orig.set(n, o); }
      else if (orig.has(n)) { n.nodeValue = orig.get(n); orig.delete(n); }
